<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/server/ads-review/Review.php';
require dirname(__DIR__,2).'/server/ads-review/Pilot.php';
require dirname(__DIR__,2).'/server/ads-review/Gemini.php';
require dirname(__DIR__,2).'/server/ads-review/GeminiHttps.php';
require dirname(__DIR__,2).'/server/ads-review/VerifiedAccess.php';
use Lienzo\Ads\{Contract,ReviewError,PrivateFiles,GeminiCredentials,GeminiHttpsTransport,GeminiProvider,
    PilotStore,ReviewService,GeminiPilotReview,VerifiedEmailAccess,VerifiedGeminiReview,AdsHttpsGuard};
$base=$argv[1]??throw new RuntimeException('Supply a fresh private directory');
$root=dirname(__DIR__,2);$tests=[];$index=0;$now=strtotime('2026-11-04T12:00:00-05:00');
function check(bool $ok,string $why='Assertion failed'):void {if(!$ok)throw new RuntimeException($why);}
function test(string $name,callable $work):void {global $tests;$work();$tests[]=$name;}
function error(callable $work,int $status,string $reason):void {try{$work();}catch(ReviewError $e){check($e->status===$status&&$e->reason===$reason,'Unexpected '.$e->reason);return;}throw new RuntimeException('Expected '.$reason);}
function secret():GeminiCredentials {return GeminiCredentials::fromValues(['schemaVersion'=>1,'projectId'=>GeminiCredentials::PROJECT,'geminiApiKey'=>'SYNTHETIC_ONLY_NOT_A_REAL_GOOGLE_KEY_12345']);}
function request():array {
    $d=['language'=>'es','business'=>'Fictional Studio','url'=>'https://example.com/offer','path1'=>'','path2'=>'','terms'=>'service',
        'headlines'=>[['text'=>'Conoce el servicio','pin'=>'']],'descriptions'=>[['text'=>'Consulta las condiciones.','pin'=>'']]];
    return ['schemaVersion'=>1,'requestId'=>'12345678-1234-4234-8234-123456789012','draftRevision'=>hash('sha256',Contract::canonical($d)),
        'locale'=>'es-CO','goal'=>'Claridad','draft'=>$d,'constraints'=>[],
        'evidence'=>[['id'=>'offer','text'=>'Primero, tu valoración','sourceUrl'=>$d['url'],'scope'=>'offer','ownerConfirmed'=>true,'observedOn'=>'2026-11-04']],
        'consent'=>['version'=>'gemini-review-v1','confirmed'=>true]];
}
function specification():array {global $now;return (new GeminiProvider(null,fn()=>$now))->specification(request());}
function access():array {
    global $base,$root,$index,$now;
    $dir=$base.'/case-'.(++$index);$a=new VerifiedEmailAccess($dir,$root,str_repeat('synthetic-pepper-',3),function()use(&$now){return $now;});
    return [$a,$dir];
}
function login(VerifiedEmailAccess $a,string $email='creator@example.com',?string $nonce=null):array {
    $nonce??=bin2hex(random_bytes(32));$messages=[];
    $r=$a->start($email,$nonce,'192.0.2.1',function($m)use(&$messages){$messages[]=$m;return true;});
    check(count($messages)===1);preg_match('/\b([0-9]{8})\b/',$messages[0]['text'],$match);
    return [$a->verify($r['challengeId'],$match[1],$nonce,'192.0.2.1'),$nonce,$r['challengeId'],$match[1]];
}
function server():array {return ['HTTPS'=>'on','REQUEST_METHOD'=>'POST','HTTP_HOST'=>'lienzo.tools','HTTP_ORIGIN'=>'https://lienzo.tools','CONTENT_TYPE'=>'application/json'];}

if(in_array($argv[2]??'',['setup-verify-race','setup-start-race'],true)) {
    [$a,$dir]=access();$a->invite('creator@example.com');
    if($argv[2]==='setup-start-race'){echo json_encode(['directory'=>$dir]);exit;}
    $mail=[];$n=str_repeat('a',64);$r=$a->start('creator@example.com',$n,'192.0.2.1',function($m)use(&$mail){$mail[]=$m;return true;});
    preg_match('/\b([0-9]{8})\b/',$mail[0]['text'],$m);echo json_encode(['directory'=>$dir,'id'=>$r['challengeId'],'code'=>$m[1],'nonce'=>$n]);exit;
}
if(in_array($argv[2]??'',['worker-verify','worker-start'],true)) {
    $a=new VerifiedEmailAccess($base,$root,str_repeat('synthetic-pepper-',3),fn()=>$now);
    try {
        if($argv[2]==='worker-verify')$a->verify($argv[3],$argv[4],$argv[5],'192.0.2.1');
        else $a->start('creator@example.com',bin2hex(random_bytes(32)),'192.0.2.1',function()use($base){file_put_contents($base.'/simulated-mails.txt',"simulated\n",FILE_APPEND|LOCK_EX);return true;});
        echo json_encode(['status'=>200]);
    } catch(ReviewError $e){echo json_encode(['status'=>$e->status]);}exit;
}

test('private directories are rejected before creating anything inside public root',function(){global $root;$dir=$root.'/output/never-create-access';error(fn()=>PrivateFiles::directory($dir,$root),503,'PRIVATE_STORAGE_REQUIRED');check(!is_dir($dir));});
test('relative traversal and URL storage paths fail closed',function(){global $root;foreach(['relative/path','/tmp/../elsewhere','https://example.com/key']as$p)error(fn()=>PrivateFiles::directory($p,$root),503,'PRIVATE_STORAGE_REQUIRED');});
test('POSIX private owner and permissions are explicit',function(){PrivateFiles::permissions(0100600,123,false,123);PrivateFiles::permissions(0040700,123,true,123);foreach([0100644,0100660,0100000]as$m)error(fn()=>PrivateFiles::permissions($m,123,false,123),503,'PRIVATE_PERMISSIONS_REQUIRED');error(fn()=>PrivateFiles::permissions(0100600,124,false,123),503,'PRIVATE_PERMISSIONS_REQUIRED');});
test('Windows cannot pretend mode bits establish secret ACL privacy',function(){global $root;if(PHP_OS_FAMILY==='Windows')error(fn()=>GeminiCredentials::fromFile('/not-a-real-secret',$root),503,'SECRET_STORAGE_PLATFORM_NOT_VERIFIED');else error(fn()=>GeminiCredentials::fromFile('/not-a-real-secret',$root),503,'PRIVATE_SECRET_UNAVAILABLE');});
test('credential validation accepts only the Lienzo project and bounded header-safe values',function(){$v=['schemaVersion'=>1,'projectId'=>GeminiCredentials::PROJECT,'geminiApiKey'=>'SYNTHETIC_ONLY_NOT_A_REAL_GOOGLE_KEY_12345'];foreach(['another-project',null]as$p){$b=$v;$b['projectId']=$p;error(fn()=>GeminiCredentials::fromValues($b),503,'PRIVATE_SECRET_INVALID');}foreach(["bad\r\nHeader: value",'REPLACE_WITH_REAL_KEY','short']as$key){$b=$v;$b['geminiApiKey']=$key;error(fn()=>GeminiCredentials::fromValues($b),503,'PRIVATE_SECRET_INVALID');}});
test('credentials cannot be serialized or accidentally dumped',function(){$s=secret();ob_start();var_dump($s);$dump=ob_get_clean();check(!str_contains($dump,'SYNTHETIC_ONLY')&&str_contains($dump,'redacted'));check(json_encode($s)==='{}');error(fn()=>serialize($s),503,'SECRET_SERIALIZATION_FORBIDDEN');});
test('header-safe auth key encodings do not depend on a guessed Google prefix',function(){$s=GeminiCredentials::fromValues(['schemaVersion'=>1,'projectId'=>GeminiCredentials::PROJECT,'geminiApiKey'=>'SYNTHETIC.auth+encoding/with=padding_123']);check(str_contains($s->header(),'auth+encoding/with=padding'));});
test('disabled transport neither reads credentials nor sends',function(){$reads=0;$calls=0;$t=new GeminiHttpsTransport(function()use(&$reads){$reads++;return secret();},false,function()use(&$calls){$calls++;return [];});error(fn()=>$t(specification()),503,'GEMINI_TRANSPORT_DISABLED');check($reads===0&&$calls===0);});
test('prepared HTTPS request adds the credential only at the transport boundary',function(){$calls=0;$t=new GeminiHttpsTransport(fn()=>secret(),true,function($spec,$headers)use(&$calls){$calls++;check($spec['url']===GeminiProvider::ENDPOINT);check(count($headers)===3&&str_starts_with($headers[2],'x-goog-api-key: SYNTHETIC_ONLY'));return ['status'=>200,'body'=>'{}'];});check($t(specification())['status']===200&&$calls===1);check(!str_contains(specification()['body'],'SYNTHETIC_ONLY'));});
foreach(['url'=>'https://example.com/steal','method'=>'GET','timeoutSeconds'=>300,'maxResponseBytes'=>9999999]as$key=>$value)test('transport rejects request override '.$key,function()use($key,$value){$reads=0;$spec=specification();$spec[$key]=$value;$t=new GeminiHttpsTransport(function()use(&$reads){$reads++;return secret();},true,fn()=>[]);error(fn()=>$t($spec),503,'INVALID_GEMINI_TRANSPORT_REQUEST');check($reads===0);});
test('transport rejects tools model and header injection before the secret is read',function(){foreach(['model'=>'gemini-pro-latest','tools'=>[['type'=>'google_search']],'store'=>true]as$k=>$v){$spec=specification();$b=json_decode($spec['body'],true);$b[$k]=$v;$spec['body']=Contract::canonical($b);$t=new GeminiHttpsTransport(fn()=>throw new RuntimeException('Should not read'),true,fn()=>[]);error(fn()=>$t($spec),503,'INVALID_GEMINI_TRANSPORT_REQUEST');}$spec=specification();$spec['headers']['Authorization']='injected';error(fn()=>(new GeminiHttpsTransport(fn()=>secret(),true,fn()=>[]))($spec),503,'INVALID_GEMINI_TRANSPORT_REQUEST');});
test('wire private exceptions are sanitized without a retry',function(){$calls=0;$t=new GeminiHttpsTransport(fn()=>secret(),true,function()use(&$calls){$calls++;throw new RuntimeException('SECRET_DETAIL');});error(fn()=>$t(specification()),502,'PROVIDER_UNAVAILABLE');check($calls===1);});
test('private credential loader exceptions are sanitized',function(){$t=new GeminiHttpsTransport(fn()=>throw new RuntimeException('PRIVATE_PATH_AND_KEY'),true,fn()=>[]);error(fn()=>$t(specification()),503,'PRIVATE_SECRET_UNAVAILABLE');});
test('missing cURL does not read the credential',function(){if(!extension_loaded('curl')){$reads=0;$t=new GeminiHttpsTransport(function()use(&$reads){$reads++;return secret();},true);error(fn()=>$t(specification()),503,'CURL_REQUIRED');check($reads===0);}});
test('valid direct HTTPS Origin and CSRF are required',function(){$csrf=str_repeat('a',64);AdsHttpsGuard::post(server(),$csrf,$csrf);foreach(['HTTPS'=>'off','REQUEST_METHOD'=>'GET','HTTP_HOST'=>'other.example','HTTP_ORIGIN'=>'https://other.example','CONTENT_TYPE'=>'text/plain']as$k=>$v){$s=server();$s[$k]=$v;error(fn()=>AdsHttpsGuard::post($s,$csrf,$csrf),403,'ACCESS_REQUIRED');}error(fn()=>AdsHttpsGuard::post(server(),$csrf,str_repeat('b',64)),403,'ACCESS_REQUIRED');});
test('forwarded headers cannot forge HTTPS',function(){$s=server();unset($s['HTTPS']);$s['HTTP_X_FORWARDED_PROTO']='https';$s['HTTP_X_FORWARDED_HOST']='lienzo.tools';error(fn()=>AdsHttpsGuard::post($s,str_repeat('a',64),str_repeat('a',64)),403,'ACCESS_REQUIRED');});
test('cookie is host-only Secure HttpOnly and Strict',function(){$v=AdsHttpsGuard::cookieOptions(123);check($v===['expires'=>123,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);check(str_starts_with(AdsHttpsGuard::COOKIE_NAME,'__Host-')&&!isset($v['domain']));});
test('Google notice is independent in Spanish and English',function(){foreach(['es','en']as$l){$n=AdsHttpsGuard::consent($l);check($n['version']==='gemini-review-v1'&&str_contains($n['text'],'Google Gemini'));}error(fn()=>AdsHttpsGuard::consent('fr'),400,'INVALID_LANGUAGE');});
test('allowlist is separate from newsletter membership and does not send to unknown addresses',function(){[$a]=access();$sent=0;$reply=$a->start('unknown@example.com',str_repeat('a',64),'192.0.2.1',function()use(&$sent){$sent++;return true;});check($reply['accepted']===true&&strlen($reply['challengeId'])===32&&$sent===0);});
test('known and unknown addresses have the same public reply shape',function(){[$a]=access();$a->invite('creator@example.com');$one=$a->start('creator@example.com',str_repeat('a',64),'192.0.2.1',fn()=>true);$two=$a->start('unknown@example.com',str_repeat('a',64),'192.0.2.1',fn()=>true);check(array_keys($one)===array_keys($two)&&$one['accepted']===$two['accepted']);});
test('email input rejects header injection and unsupported international addresses',function(){[$a]=access();foreach(["x@example.com\r\nBcc: another@example.com",'not-an-email','creatór@example.com']as$email)error(fn()=>$a->invite($email),400,'INVALID_EMAIL');});
test('email code has a ten-minute expiry and needs the originating browser',function(){[$a]=access();$a->invite('creator@example.com');$mail=[];$nonce=str_repeat('a',64);$r=$a->start('creator@example.com',$nonce,'192.0.2.1',function($m)use(&$mail){$mail[]=$m;return true;});preg_match('/\b([0-9]{8})\b/',$mail[0]['text'],$m);error(fn()=>$a->verify($r['challengeId'],$m[1],str_repeat('b',64),'192.0.2.1'),403,'ACCESS_REQUIRED');$s=$a->verify($r['challengeId'],$m[1],$nonce,'192.0.2.1');$a->authorize($s['sessionToken'],$s['csrfToken']);});
test('expired code cannot create a session',function(){global $now;$old=$now;[$a]=access();$a->invite('creator@example.com');$mail=[];$n=str_repeat('a',64);$r=$a->start('creator@example.com',$n,'192.0.2.1',function($m)use(&$mail){$mail[]=$m;return true;});preg_match('/\b([0-9]{8})\b/',$mail[0]['text'],$m);$now+=600;try{error(fn()=>$a->verify($r['challengeId'],$m[1],$n,'192.0.2.1'),403,'ACCESS_REQUIRED');}finally{$now=$old;}});
test('five incorrect guesses persist and exhaust the challenge',function(){[$a]=access();$a->invite('creator@example.com');$mail=[];$n=str_repeat('a',64);$r=$a->start('creator@example.com',$n,'192.0.2.1',function($m)use(&$mail){$mail[]=$m;return true;});preg_match('/\b([0-9]{8})\b/',$mail[0]['text'],$m);$wrong=$m[1]==='00000000'?'11111111':'00000000';for($i=0;$i<5;$i++)error(fn()=>$a->verify($r['challengeId'],$wrong,$n,'192.0.2.1'),403,'ACCESS_REQUIRED');error(fn()=>$a->verify($r['challengeId'],$m[1],$n,'192.0.2.1'),403,'ACCESS_REQUIRED');});
test('a verified code is single-use',function(){[$a]=access();$a->invite('creator@example.com');[$s,$n,$id,$code]=login($a);error(fn()=>$a->verify($id,$code,$n,'192.0.2.1'),403,'ACCESS_REQUIRED');$a->authorize($s['sessionToken'],$s['csrfToken']);});
test('resend invalidates only the prior code from the same browser',function(){[$a]=access();$a->invite('creator@example.com');$mail=[];$n=str_repeat('a',64);$send=function($m)use(&$mail){$mail[]=$m;return true;};$one=$a->start('creator@example.com',$n,'192.0.2.1',$send);$two=$a->start('creator@example.com',$n,'192.0.2.1',$send);preg_match('/\b([0-9]{8})\b/',$mail[0]['text'],$m);error(fn()=>$a->verify($one['challengeId'],$m[1],$n,'192.0.2.1'),403,'ACCESS_REQUIRED');preg_match('/\b([0-9]{8})\b/',$mail[1]['text'],$m);check(isset($a->verify($two['challengeId'],$m[1],$n,'192.0.2.1')['sessionToken']));});
test('request rate is persistent across browser nonces',function(){[$a]=access();$a->invite('creator@example.com');for($i=0;$i<3;$i++)$a->start('creator@example.com',bin2hex(random_bytes(32)),'192.0.2.1',fn()=>true);error(fn()=>$a->start('creator@example.com',str_repeat('a',64),'192.0.2.1',fn()=>true),429,'ACCESS_RATE_LIMIT');});
test('request IP rate covers multiple addresses',function(){[$a]=access();for($i=0;$i<5;$i++)$a->start('unknown'.$i.'@example.com',bin2hex(random_bytes(32)),'192.0.2.1',fn()=>true);error(fn()=>$a->start('another@example.com',str_repeat('a',64),'192.0.2.1',fn()=>true),429,'ACCESS_RATE_LIMIT');});
test('allowlist expiry prevents starting another login',function(){global $now;$old=$now;[$a]=access();$a->invite('creator@example.com','es',1);$now+=1;try{$sent=0;$r=$a->start('creator@example.com',str_repeat('a',64),'192.0.2.1',function()use(&$sent){$sent++;return true;});check($r['accepted']===true&&$sent===0);}finally{$now=$old;}});
test('allowlist capacity cannot be renewed by revoking an old participant',function(){[$a]=access();for($i=0;$i<20;$i++)$a->invite('creator'.$i.'@example.com');$a->revoke('creator0@example.com');error(fn()=>$a->invite('creator20@example.com'),403,'PILOT_FULL');});
test('failed mail acceptance invalidates the challenge without exposing delivery status',function(){[$a,$dir]=access();$a->invite('creator@example.com');$r=$a->start('creator@example.com',str_repeat('a',64),'192.0.2.1',fn()=>false);check($r['accepted']===true);$db=new PDO('sqlite:'.$dir.'/verified-access.sqlite');check((int)$db->query('SELECT used FROM login_challenge')->fetchColumn()===1);});
test('successful login rotates session and CSRF for the same browser',function(){[$a]=access();$a->invite('creator@example.com');[$old,$n]=login($a);[$new]=login($a,'creator@example.com',$n);check($old['sessionToken']!==$new['sessionToken']&&$old['csrfToken']!==$new['csrfToken']);error(fn()=>$a->authorize($old['sessionToken'],$old['csrfToken']),403,'ACCESS_REQUIRED');$a->authorize($new['sessionToken'],$new['csrfToken']);});
test('CSRF mismatch and logout block reuse',function(){[$a]=access();$a->invite('creator@example.com');[$s]=login($a);error(fn()=>$a->authorize($s['sessionToken'],str_repeat('b',64)),403,'ACCESS_REQUIRED');$a->logout($s['sessionToken'],$s['csrfToken']);error(fn()=>$a->authorize($s['sessionToken'],$s['csrfToken']),403,'ACCESS_REQUIRED');});
test('session expires after eight hours',function(){global $now;$old=$now;[$a]=access();$a->invite('creator@example.com');[$s]=login($a);$now+=28800;try{error(fn()=>$a->authorize($s['sessionToken'],$s['csrfToken']),403,'ACCESS_REQUIRED');}finally{$now=$old;}});
test('revocation blocks existing sessions and does not revive them on reinvitation',function(){[$a]=access();$a->invite('creator@example.com');[$s]=login($a);$a->revoke('creator@example.com');error(fn()=>$a->authorize($s['sessionToken'],$s['csrfToken']),403,'ACCESS_REQUIRED');$a->invite('creator@example.com');error(fn()=>$a->authorize($s['sessionToken'],$s['csrfToken']),403,'ACCESS_REQUIRED');});
test('private DB never stores the email code token csrf or plaintext address',function(){[$a,$dir]=access();$a->invite('creator@example.com');[$s,$n,$id,$code]=login($a);$db=new PDO('sqlite:'.$dir.'/verified-access.sqlite');$dump='';foreach(['allowed_email','login_challenge','verified_session','access_attempt']as$t)$dump.=json_encode($db->query('SELECT * FROM '.$t)->fetchAll(PDO::FETCH_ASSOC));foreach(['creator@example.com',$s['sessionToken'],$s['csrfToken'],$code,$n]as$v)check(!str_contains($dump,$v));});
test('English invite delivers English access copy',function(){[$a]=access();$a->invite('creator@example.com','en');$m=[];$a->start('creator@example.com',str_repeat('a',64),'192.0.2.1',function($x)use(&$m){$m[]=$x;return true;});check(str_contains($m[0]['subject'],'access code')&&str_contains($m[0]['text'],'10 minutes'));});
test('ES and EN sessions for one email bind the same persistent pilot grant',function(){global $root;[$a,$dir]=access();$a->invite('creator@example.com','es');[$es]=login($a);$pilot=new PilotStore($dir,$root);$one=$a->grant($es['sessionToken'],$es['csrfToken'],$pilot);$a->invite('CREATOR@example.com','en');[$en]=login($a,'CREATOR@example.com');check($one===$a->grant($en['sessionToken'],$en['csrfToken'],$pilot));});
test('prepared verified review remains disabled by default',function(){global $root,$now;[$a,$dir]=access();$pilot=new PilotStore($dir,$root);$r=new GeminiPilotReview($pilot,new ReviewService($dir,$root),new GeminiProvider(null,fn()=>$now));$gate=new VerifiedGeminiReview($a,$pilot,$r);error(fn()=>$gate->review(request(),str_repeat('a',64),str_repeat('b',64)),503,'GEMINI_PILOT_DISABLED');});
test('end-to-end verified review uses only synthetic email and HTTPS transport',function(){global $root,$now;[$a,$dir]=access();$a->invite('creator@example.com');[$session]=login($a);$r=request();$calls=0;
    $wire=function($spec,$headers)use(&$calls,$r){$calls++;$value=['schemaVersion'=>1,'requestId'=>$r['requestId'],'draftRevision'=>$r['draftRevision'],'status'=>'review_required','suggestions'=>[['id'=>'one','field'=>'headlines','index'=>0,'originalText'=>$r['draft']['headlines'][0]['text'],'proposedText'=>'Primero, tu valoración','reason'=>'Aclara el primer paso.','evidenceIds'=>['offer'],'requiresOwnerConfirmation'=>true]],'missingFacts'=>[],'warnings'=>[]];return ['status'=>200,'body'=>Contract::canonical(['model'=>GeminiProvider::MODEL,'status'=>'completed','steps'=>[['type'=>'model_output','content'=>[['type'=>'text','text'=>Contract::canonical($value)]]]],'usage'=>['total_input_tokens'=>100,'total_output_tokens'=>20,'total_thought_tokens'=>10,'total_cached_tokens'=>0,'total_tool_use_tokens'=>0,'total_tokens'=>130]])];};
    $transport=new GeminiHttpsTransport(fn()=>secret(),true,$wire);$provider=new GeminiProvider($transport(...),fn()=>$now);
    $pilot=new PilotStore($dir,$root,['budgetMicroUsd'=>5000000]);$gate=new VerifiedGeminiReview($a,$pilot,new GeminiPilotReview($pilot,new ReviewService($dir,$root),$provider),true);
    error(fn()=>$gate->review($r,str_repeat('a',64),str_repeat('b',64)),403,'ACCESS_REQUIRED');check($calls===0);
    $bad=$r;$bad['consent']['confirmed']=false;error(fn()=>$gate->review($bad,$session['sessionToken'],$session['csrfToken']),403,'CONSENT_REQUIRED');check($calls===0);
    $one=$gate->review($r,$session['sessionToken'],$session['csrfToken']);check($one['status']==='review_required');check($gate->review($r,$session['sessionToken'],$session['csrfToken'])===$one&&$calls===1);
    $a->revoke('creator@example.com');error(fn()=>$gate->review($r,$session['sessionToken'],$session['csrfToken']),403,'ACCESS_REQUIRED');check($calls===1);
});
test('public pages and local routers do not enable the prepared secure path',function(){global $root;$r=file_get_contents($root.'/server/ads-review/dev-router.php');check(!str_contains($r,'VerifiedAccess.php')&&!str_contains($r,'GeminiHttps.php'));foreach(['/herramientas/anuncios/index.html','/en/tools/ads/index.html']as$p)check(!str_contains(file_get_contents($root.$p),'gemini-review-v1'));});

echo json_encode(['passed'=>count($tests),'network'=>'simulated wire and mailer only','tests'=>$tests],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);
